import{_ as l,a0 as d,w as o,s as r,ao as p,I as i,x as a,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 系統上交換空間的介紹 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統上交換空間的介紹 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統上交換空間的介紹 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統上交換空間的介紹 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180926 An introduction to swap space on Linux systems","title":"Linux 系統上交換空間的介紹","tag":"201810","desc":""},"relativePath":"201810/20180926 An introduction to swap space on Linux systems.md","filePath":"[post].md"}'),h={name:"201810/20180926 An introduction to swap space on Linux systems.md"};function c(u,s,g,k,b,f){const e=d("Link");return o(),r("div",null,[s[25]||(s[25]=p('<h1 id="linux-系統上交換空間的介紹" tabindex="-1">Linux 系統上交換空間的介紹 <a class="header-anchor" href="#linux-系統上交換空間的介紹" aria-label="Permalink to “Linux 系統上交換空間的介紹”">​</a></h1><blockquote><p>學習如何修改你的系統上的交換空間的容量，以及你到底需要多大的交換空間。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/fail_progress_cycle_momentum_arrow.png?itok=q-ZFa_Eh" alt=""></p><p>當今無論什麼操作系統<ruby>交換<rt>Swap</rt></ruby>空間是非常常見的。Linux 使用交換空間來增加主機可用的虛擬內存。它可以在常規文件或邏輯捲上使用一個或多個專用交換分區或交換文件。</p><p>典型計算機中有兩種基本類型的內存。第一種類型，隨機存取存儲器 (RAM)，用於存儲計算機使用的數據和程序。只有程序和數據存儲在 RAM 中，計算機才能使用它們。隨機存儲器是易失性存儲器；也就是説，如果計算機關閉了，存儲在 RAM 中的數據就會丟失。</p><p>硬盤是用於長期存儲數據和程序的磁性介質。該磁介質可以很好的保存數據；即使計算機斷電，存儲在磁盤上的數據也會保留下來。CPU（中央處理器）不能直接訪問硬盤上的程序和數據；它們必須首先複製到 RAM 中，RAM 是 CPU 訪問代碼指令和操作數據的地方。在引導過程中，計算機將特定的操作系統程序（如內核、init 或 systemd）以及硬盤上的數據複製到 RAM 中，在 RAM 中，計算機的處理器 CPU 可以直接訪問這些數據。</p><h3 id="交換空間" tabindex="-1">交換空間 <a class="header-anchor" href="#交換空間" aria-label="Permalink to “交換空間”">​</a></h3><p>交換空間是現代 Linux 系統中的第二種內存類型。交換空間的主要功能是當全部的 RAM 被佔用並且需要更多內存時，用磁盤空間代替 RAM 內存。</p><p>例如，假設你有一個 8GB RAM 的計算機。如果你啓動的程序沒有填滿 RAM，一切都好，不需要交換。假設你在處理電子表格，當添加更多的行時，你電子表格會增長，加上所有正在運行的程序，將會佔用全部的 RAM 。如果這時沒有可用的交換空間，你將不得不停止處理電子表格，直到關閉一些其他程序來釋放一些 RAM 。</p><p>內核使用一個內存管理程序來檢測最近沒有使用的內存塊（內存頁）。內存管理程序將這些相對不經常使用的內存頁交換到硬盤上專門指定用於“分頁”或交換的特殊分區。這會釋放 RAM，為輸入電子表格更多數據騰出了空間。那些換出到硬盤的內存頁面被內核的內存管理代碼跟蹤，如果需要，可以被分頁回 RAM。</p><p>Linux 計算機中的內存總量是 RAM + 交換分區，交換分區被稱為虛擬內存.</p><h3 id="linux-交換分區類型" tabindex="-1">Linux 交換分區類型 <a class="header-anchor" href="#linux-交換分區類型" aria-label="Permalink to “Linux 交換分區類型”">​</a></h3><p>Linux 提供了兩種類型的交換空間。默認情況下，大多數 Linux 在安裝時都會創建一個交換分區，但是也可以使用一個特殊配置的文件作為交換文件。交換分區顧名思義就是一個標準磁盤分區，由 <code>mkswap</code> 命令指定交換空間。</p><p>如果沒有可用磁盤空間來創建新的交換分區，或者卷組中沒有空間為交換空間創建邏輯卷，則可以使用交換文件。這只是一個創建好並預分配指定大小的常規文件。然後運行 <code>mkswap</code> 命令將其配置為交換空間。除非絕對必要，否則我不建議使用文件來做交換空間。（LCTT 譯註：Ubuntu 近來的版本採用了交換文件而非交換空間，所以我對於這種説法保留看法）</p><h3 id="頻繁交換" tabindex="-1">頻繁交換 <a class="header-anchor" href="#頻繁交換" aria-label="Permalink to “頻繁交換”">​</a></h3><p>當總虛擬內存（RAM 和交換空間）變得快滿時，可能會發生頻繁交換。系統花了太多時間在交換空間和 RAM 之間做內存塊的頁面切換，以至於幾乎沒有時間用於實際工作。這種情況的典型症狀是：系統變得緩慢或完全無反應，硬盤指示燈幾乎持續亮起。</p><p>使用 <code>free</code> 的命令來顯示 CPU 負載和內存使用情況，你會發現 CPU 負載非常高，可能達到系統中 CPU 內核數量的 30 到 40 倍。另一個情況是 RAM 和交換空間幾乎完全被分配了。</p><p>事實上，查看 SAR（系統活動報告）數據也可以顯示這些內容。在我的每個系統上都安裝 SAR ，並將這些用於數據分析。</p><h3 id="交換空間的正確大小是多少" tabindex="-1">交換空間的正確大小是多少？ <a class="header-anchor" href="#交換空間的正確大小是多少" aria-label="Permalink to “交換空間的正確大小是多少？”">​</a></h3><p>許多年前，硬盤上分配給交換空間大小是計算機上的 RAM 的兩倍（當然，這是大多數計算機的 RAM 以 KB 或 MB 為單位的時候）。因此，如果一台計算機有 64KB 的 RAM，應該分配 128KB 的交換分區。該規則考慮到了這樣的事實情況，即 RAM 大小在當時非常小，分配超過 2 倍的 RAM 用於交換空間並不能提高性能。使用超過兩倍的 RAM 進行交換，比實際執行有用的工作的時候，大多數系統將花費更多的時間。</p><p>RAM 現在已經很便宜了，如今大多數計算機的 RAM 都達到了幾十億字節。我的大多數新電腦至少有 8GB 內存，一台有 32GB 內存，我的主工作站有 64GB 內存。我的舊電腦有 4 到 8GB 的內存。</p>',21)),i("p",null,[s[1]||(s[1]=a("當操作具有大量 RAM 的計算機時，交換空間的限制性能係數遠低於 2 倍。",-1)),n(e,{href:"https://docs.fedoraproject.org/en-US/fedora/f28/install-guide/"},{default:t(()=>[...s[0]||(s[0]=[a("Fedora 28 在線安裝指南",-1)])]),_:1}),s[2]||(s[2]=a(" 定義了當前關於交換空間分配的方法。下面內容是我提出的建議。",-1))]),s[26]||(s[26]=p(`<p>下表根據系統中的 RAM 大小以及是否有足夠的內存讓系統休眠，提供了交換分區的推薦大小。建議的交換分區大小是在安裝過程中自動建立的。但是，為了滿足系統休眠，您需要在自定義分區階段編輯交換空間。</p><p><em>表 1: Fedora 28 文檔中推薦的系統交換空間</em></p><div class="table-wrap"><table><thead><tr><th><strong>系統內存大小</strong></th><th><strong>推薦的交換空間</strong></th><th><strong>推薦的交換空間大小（支持休眠模式）</strong></th></tr></thead><tbody><tr><td>小於 2 GB</td><td>2 倍 RAM</td><td>3 倍 RAM</td></tr><tr><td>2 GB - 8 GB</td><td>等於 RAM 大小</td><td>2 倍 RAM</td></tr><tr><td>8 GB - 64 GB</td><td>0.5 倍 RAM</td><td>1.5 倍 RAM</td></tr><tr><td>大於 64 GB</td><td>工作量相關</td><td>不建議休眠模式</td></tr></tbody></table></div><p>在上面列出的每個範圍之間的邊界(例如，具有 2GB、8GB 或 64GB 的系統 RAM)，請根據所選交換空間和支持休眠功能請謹慎使用。如果你的系統資源允許，增加交換空間可能會帶來更好的性能。</p><p>當然，大多數 Linux 管理員對多大的交換空間量有自己的想法。下面的表2 包含了基於我在多種環境中的個人經歷所做出的建議。這些可能不適合你，但是和表 1 一樣，它們可能對你有所幫助。</p><p><em>表 2: 作者推薦的系統交換空間</em></p><div class="table-wrap"><table><thead><tr><th>RAM 大小</th><th>推薦的交換空間</th></tr></thead><tbody><tr><td>≤ 2GB</td><td>2X RAM</td></tr><tr><td>2GB – 8GB</td><td>= RAM</td></tr><tr><td>&gt;8GB</td><td>8GB</td></tr></tbody></table></div><p>這兩個表中共同點，隨着 RAM 數量的增加，超過某一點增加更多交換空間只會導致在交換空間幾乎被全部使用之前就發生頻繁交換。根據以上建議，則應儘可能添加更多 RAM，而不是增加更多交換空間。如類似影響系統性能的情況一樣，請使用最適合你的建議。根據 Linux 環境中的條件進行測試和更改是需要時間和精力的。</p><h3 id="向非-lvm-磁盤環境添加更多交換空間" tabindex="-1">向非 LVM 磁盤環境添加更多交換空間 <a class="header-anchor" href="#向非-lvm-磁盤環境添加更多交換空間" aria-label="Permalink to “向非 LVM 磁盤環境添加更多交換空間”">​</a></h3><p>面對已安裝 Linux 的主機並對交換空間的需求不斷變化，有時有必要修改系統定義的交換空間的大小。此過程可用於需要增加交換空間大小的任何情況。它假設有足夠的可用磁盤空間。此過程還假設磁盤分區為 “原始的” EXT4 和交換分區，而不是使用邏輯卷管理（LVM）。</p><p>基本步驟很簡單:</p><ol><li>關閉現有的交換空間。</li><li>創建所需大小的新交換分區。</li><li>重讀分區表。</li><li>將分區配置為交換空間。</li><li>添加新分區到 <code>/etc/fstab</code>。</li><li>打開交換空間。</li></ol><p>應該不需要重新啓動機器。</p><p>為了安全起見，在關閉交換空間前，至少你應該確保沒有應用程序在運行，也沒有交換空間在使用。<code>free</code> 或 <code>top</code> 命令可以告訴你交換空間是否在使用中。為了更安全，您可以恢復到運行級別 1 或單用户模式。</p><p>使用關閉所有交換空間的命令關閉交換分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>swapoff -a</span></span></code></pre></div><p>現在查看硬盤上的現有分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk -l</span></span></code></pre></div><p>這將顯示每個驅動器上的分區表。按編號標識當前的交換分區。</p><p>使用以下命令在交互模式下啓動 <code>fdisk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk /dev/&lt;device name&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fdisk /dev/sda</span></span></code></pre></div><p>此時，<code>fdisk</code> 是交互方式的，只在指定的磁盤驅動器上進行操作。</p><p>使用 <code>fdisk</code> 的 <code>p</code> 子命令驗證磁盤上是否有足夠的可用空間來創建新的交換分區。硬盤上的空間以 512 字節的塊以及起始和結束柱面編號的形式顯示，因此您可能需要做一些計算來確定分配分區之間和末尾的可用空間。</p><p>使用 <code>n</code> 子命令創建新的交換分區。<code>fdisk</code> 會問你開始柱面。默認情況下，它選擇編號最低的可用柱面。如果你想改變這一點，輸入開始柱面的編號。</p><p><code>fdisk</code> 命令允許你以多種格式輸入分區的大小，包括最後一個柱面號或字節、KB 或 MB 的大小。例如，鍵入 4000M ，這將在新分區上提供大約 4GB 的空間，然後按回車鍵。</p><p>使用 <code>p</code> 子命令來驗證分區是否按照指定的方式創建的。請注意，除非使用結束柱面編號，否則分區可能與你指定的不完全相同。<code>fdisk</code> 命令只能在整個柱面上增量的分配磁盤空間，因此你的分區可能比你指定的稍小或稍大。如果分區不是您想要的，你可以刪除它並重新創建它。</p><p>現在指定新分區是交換分區了 。子命令 <code>t</code> 允許你指定定分區的類型。所以輸入 <code>t</code>，指定分區號，當它要求十六進制分區類型時，輸入 <code>82</code>，這是 Linux 交換分區類型，然後按回車鍵。</p><p>當你對創建的分區感到滿意時，使用 <code>w</code> 子命令將新的分區表寫入磁盤。<code>fdisk</code> 程序將退出，並在完成修改後的分區表的編寫後返回命令提示符。當 <code>fdisk</code> 完成寫入新分區表時，會收到以下消息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The partition table has been altered!</span></span>
<span class="line"><span>Calling ioctl() to re-read partition table.</span></span>
<span class="line"><span>WARNING: Re-reading the partition table failed with error 16: Device or resource busy.</span></span>
<span class="line"><span>The kernel still uses the old table.</span></span>
<span class="line"><span>The new table will be used at the next reboot.</span></span>
<span class="line"><span>Syncing disks.</span></span></code></pre></div><p>此時，你使用 <code>partprobe</code> 命令強制內核重新讀取分區表，這樣就不需要執行重新啓動機器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>partprobe</span></span></code></pre></div><p>使用命令 <code>fdisk -l</code> 列出分區，新交換分區應該在列出的分區中。確保新的分區類型是 “Linux swap”。</p><p>修改 <code>/etc/fstab</code> 文件以指向新的交換分區。如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LABEL=SWAP-sdaX   swap        swap    defaults        0 0</span></span></code></pre></div><p>其中 <code>X</code> 是分區號。根據新交換分區的位置，添加以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/dev/sdaY         swap        swap    defaults        0 0</span></span></code></pre></div><p>請確保使用正確的分區號。現在，可以執行創建交換分區的最後一步。使用 <code>mkswap</code> 命令將分區定義為交換分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkswap /dev/sdaY</span></span></code></pre></div><p>最後一步是使用以下命令啓用交換空間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>swapon -a</span></span></code></pre></div><p>你的新交換分區現在與以前存在的交換分區一起在線。您可以使用 <code>free</code> 或<code>top</code> 命令來驗證這一點。</p><h4 id="在-lvm-磁盤環境中添加交換空間" tabindex="-1">在 LVM 磁盤環境中添加交換空間 <a class="header-anchor" href="#在-lvm-磁盤環境中添加交換空間" aria-label="Permalink to “在 LVM 磁盤環境中添加交換空間”">​</a></h4><p>如果你的磁盤使用 LVM ，更改交換空間將相當容易。同樣，假設當前交換卷所在的卷組中有可用空間。默認情況下，LVM 環境中的 Fedora Linux 在安裝過程將交換分區創建為邏輯卷。您可以非常簡單地增加交換卷的大小。</p><p>以下是在 LVM 環境中增加交換空間大小的步驟:</p><ol><li>關閉所有交換空間。</li><li>增加指定用於交換空間的邏輯卷的大小。</li><li>為交換空間調整大小的卷配置。</li><li>啓用交換空間。</li></ol><p>首先，讓我們使用 <code>lvs</code> 命令（列出邏輯卷）來驗證交換空間是否存在以及交換空間是否是邏輯卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# lvs</span></span>
<span class="line"><span>  LV     VG                Attr       LSize  Pool   Origin Data%  Meta%  Move Log Cpy%Sync Convert</span></span>
<span class="line"><span>  home   fedora_studentvm1 -wi-ao----  2.00g                                                      </span></span>
<span class="line"><span>  pool00 fedora_studentvm1 twi-aotz--  2.00g               8.17   2.93                            </span></span>
<span class="line"><span>  root   fedora_studentvm1 Vwi-aotz--  2.00g pool00        8.17                                   </span></span>
<span class="line"><span>  swap   fedora_studentvm1 -wi-ao----  8.00g                                                      </span></span>
<span class="line"><span>  tmp    fedora_studentvm1 -wi-ao----  5.00g                                                      </span></span>
<span class="line"><span>  usr    fedora_studentvm1 -wi-ao---- 15.00g                                                      </span></span>
<span class="line"><span>  var    fedora_studentvm1 -wi-ao---- 10.00g                                                      </span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div><p>你可以看到當前的交換空間大小為 8GB。在這種情況下，我們希望將 2GB 添加到此交換卷中。首先，停止現有的交換空間。如果交換空間正在使用，終止正在運行的程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>swapoff -a</span></span></code></pre></div><p>現在增加邏輯卷的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# lvextend -L +2G /dev/mapper/fedora_studentvm1-swap</span></span>
<span class="line"><span>  Size of logical volume fedora_studentvm1/swap changed from 8.00 GiB (2048 extents) to 10.00 GiB (2560 extents).</span></span>
<span class="line"><span>  Logical volume fedora_studentvm1/swap successfully resized.</span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div><p>運行 <code>mkswap</code> 命令將整個 10GB 分區變成交換空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# mkswap /dev/mapper/fedora_studentvm1-swap</span></span>
<span class="line"><span>mkswap: /dev/mapper/fedora_studentvm1-swap: warning: wiping old swap signature.</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 10 GiB (10737414144 bytes)</span></span>
<span class="line"><span>no label, UUID=3cc2bee0-e746-4b66-aa2d-1ea15ef1574a</span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div><p>重新啓用交換空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# swapon -a</span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div><p>現在，使用 <code>lsblk </code> 命令驗證新交換空間是否存在。同樣，不需要重新啓動機器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# lsblk</span></span>
<span class="line"><span>NAME                                 MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>sda                                    8:0    0   60G  0 disk</span></span>
<span class="line"><span>|-sda1                                 8:1    0    1G  0 part /boot</span></span>
<span class="line"><span>\`-sda2                                 8:2    0   59G  0 part</span></span>
<span class="line"><span>  |-fedora_studentvm1-pool00_tmeta   253:0    0    4M  0 lvm  </span></span>
<span class="line"><span>  | \`-fedora_studentvm1-pool00-tpool 253:2    0    2G  0 lvm  </span></span>
<span class="line"><span>  |   |-fedora_studentvm1-root       253:3    0    2G  0 lvm  /</span></span>
<span class="line"><span>  |   \`-fedora_studentvm1-pool00     253:6    0    2G  0 lvm  </span></span>
<span class="line"><span>  |-fedora_studentvm1-pool00_tdata   253:1    0    2G  0 lvm  </span></span>
<span class="line"><span>  | \`-fedora_studentvm1-pool00-tpool 253:2    0    2G  0 lvm  </span></span>
<span class="line"><span>  |   |-fedora_studentvm1-root       253:3    0    2G  0 lvm  /</span></span>
<span class="line"><span>  |   \`-fedora_studentvm1-pool00     253:6    0    2G  0 lvm  </span></span>
<span class="line"><span>  |-fedora_studentvm1-swap           253:4    0   10G  0 lvm  [SWAP]</span></span>
<span class="line"><span>  |-fedora_studentvm1-usr            253:5    0   15G  0 lvm  /usr</span></span>
<span class="line"><span>  |-fedora_studentvm1-home           253:7    0    2G  0 lvm  /home</span></span>
<span class="line"><span>  |-fedora_studentvm1-var            253:8    0   10G  0 lvm  /var</span></span>
<span class="line"><span>  \`-fedora_studentvm1-tmp            253:9    0    5G  0 lvm  /tmp</span></span>
<span class="line"><span>sr0                                   11:0    1 1024M  0 rom  </span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div><p>您也可以使用 <code>swapon -s</code> 命令或 <code>top</code>、<code>free</code> 或其他幾個命令來驗證這一點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@studentvm1 ~]# free</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:        4038808      382404     2754072        4152      902332     3404184</span></span>
<span class="line"><span>Swap:      10485756           0    10485756</span></span>
<span class="line"><span>[root@studentvm1 ~]#</span></span></code></pre></div>`,61)),i("p",null,[s[4]||(s[4]=a("請注意，不同的命令以不同的形式顯示或要求輸入設備文件。在 ",-1)),s[5]||(s[5]=i("code",null,"/dev",-1)),s[6]||(s[6]=a(" 目錄中訪問特定設備有多種方式。在我的文章 ",-1)),n(e,{href:"https://linux.cn/article-8099-1.html"},{default:t(()=>[...s[3]||(s[3]=[a("在 Linux 中管理設備",-1)])]),_:1}),s[7]||(s[7]=a(" 中有更多關於 ",-1)),s[8]||(s[8]=i("code",null,"/dev",-1)),s[9]||(s[9]=a(" 目錄及其內容説明。",-1))]),s[27]||(s[27]=i("hr",null,null,-1)),i("p",null,[s[11]||(s[11]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/18/9/swap-space-linux-systems"},{default:t(()=>[...s[10]||(s[10]=[a("https://opensource.com/article/18/9/swap-space-linux-systems",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/dboth"},{default:t(()=>[...s[12]||(s[12]=[a("David Both",-1)])]),_:1}),s[17]||(s[17]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[13]||(s[13]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 譯者：",-1)),n(e,{href:"https://github.com/heguangzhi"},{default:t(()=>[...s[14]||(s[14]=[a("heguangzhi",-1)])]),_:1}),s[19]||(s[19]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[20]||(s[20]=[a("LCTT",-1)])]),_:1}),s[23]||(s[23]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[21]||(s[21]=[a("Linux中國",-1)])]),_:1}),s[24]||(s[24]=a(" 榮譽推出",-1))])])}const x=l(h,[["render",c]]);export{y as __pageData,x as default};
